 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            area=(r1-r0+1)*(c1-c0+1)
            density=len(comp)/area
            if len(comp)>=6 and density>=0.45:
                objects.append((color,r0,r1,c0,c1))
    out=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in objects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out

